import{_t as e,it as t,n,rt as r}from"./chunks/framework.Bc6s-rUw.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"project/bisai/1.活动背景介绍.md","filePath":"project/bisai/1.活动背景介绍.md"}`),a={name:`project/bisai/1.活动背景介绍.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>活动背景介绍</p><p>​ 重庆市第七届中小学人工智能教育展评活动由‌<strong>重庆市教育科学研究院</strong>‌主办，面向全市小学和初中学生，共设7大类项目、分3个组别进行。‌‌</p><h3 id="🏆-活动项目与分组" tabindex="-1">🏆 活动项目与分组 <a class="header-anchor" href="#🏆-活动项目与分组" aria-label="Permalink to “🏆 活动项目与分组”">​</a></h3><p>‌<strong>项目设置</strong>‌：智能硬件普及赛、智能算法普及赛、Python创意赛、智能硬件创意赛、智能硬件挑战赛、无人飞行器挑战赛、虚拟仿真机器人挑战赛。‌‌</p><p>‌<strong>组别划分</strong>‌：分为小学低段（一至四年级）、小学高段（五、六年级）和初中组，不同项目对应不同年级段。‌‌</p><h3 id="📅-关键时间节点" tabindex="-1">📅 关键时间节点 <a class="header-anchor" href="#📅-关键时间节点" aria-label="Permalink to “📅 关键时间节点”">​</a></h3><p>不同赛项的时间安排有所差异，这里整理几个重点：</p><ol><li>‌<strong>智能算法普及赛</strong>‌：学生报名截止2026年9月10日，线上初赛时间为10月8日—10月13日，各组别排名前20%入围市级决赛。</li><li>‌<strong>其他赛项（智能硬件、虚拟仿真、无人机等）</strong>‌：报名截止2026年9月20日，具体比赛规则和模拟测试安排另行通知。</li><li>‌<strong>创意类作品</strong>‌：以区县为单位组织报送，如大足区要求9月30日前提交作品。‌‌</li></ol><h3 id="⚠️-报名注意事项" tabindex="-1">⚠️ 报名注意事项 <a class="header-anchor" href="#⚠️-报名注意事项" aria-label="Permalink to “⚠️ 报名注意事项”">​</a></h3><ul><li>由‌<strong>学校统一组织报名</strong>‌，不接受个人单独报名，需先在赛事平台完成学校信息填报。</li><li>每位学生限报一项、限参加一个组别，作品须为原创，不能提交往届获奖作品。</li><li>智能硬件挑战赛、无人飞行器挑战赛直接参加市级决赛，不经过区级初选。‌‌</li></ul><p>各区县的具体选拔安排和时间可能略有差异，建议联系学校信息科技老师确认本区的报名流程和截止日期。</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};